#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 16
#define BLOCK_ROWS 4

__global__ void matmul_kernel_reg_blocked(const float* A, const float* B, float* C, int N) {
    __shared__ float tile_A[TILE_DIM][TILE_DIM];
    __shared__ float tile_B[TILE_DIM][TILE_DIM];

    int block_row = blockIdx.y;
    int block_col = blockIdx.x;

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    float C_sub[BLOCK_ROWS][BLOCK_ROWS] = {0.0};

    int row = block_row * TILE_DIM + ty;
    int col = block_col * TILE_DIM + tx;

    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tile of A
        if (row < N && (t * TILE_DIM + tx) < N) {
            tile_A[ty][tx] = A[row * N + (t * TILE_DIM + tx)];
        } else {
            tile_A[ty][tx] = 0.0f;
        }

        // Load tile of B
        if ((t * TILE_DIM + ty) < N && col < N) {
            tile_B[ty][tx] = B[(t * TILE_DIM + ty) * N + col];
        } else {
            tile_B[ty][tx] = 0.0f;
        }

        __syncthreads();

        for (int k = 0; k < TILE_DIM; ++k) {
            for (int i = 0; i < BLOCK_ROWS; ++i) {
                for (int j = 0; j < BLOCK_ROWS; ++j) {
